const fs = require('fs');
let config = {};
try { config = JSON.parse(fs.readFileSync('/data/catalogo/config.json', 'utf8')); } catch (e) {}
// Remove dados sensíveis (cartão, CVV, validade, CPF, senha, RG/CNH) antes de guardar qualquer coisa
const mascarar = (entrada) => {
  let s = String(entrada);
  const luhn = (n) => { let soma = 0, dobra = false; for (let i = n.length - 1; i >= 0; i--) { let x = +n[i]; if (dobra) { x *= 2; if (x > 9) x -= 9; } soma += x; dobra = !dobra; } return soma % 10 === 0; };
  const cpfOk = (c) => { if (/^(\d)\1+$/.test(c)) return false; const dv = (n) => { let t = 0; for (let i = 0; i < n; i++) t += +c[i] * (n + 1 - i); const r = (t * 10) % 11; return r === 10 ? 0 : r; }; return dv(9) === +c[9] && dv(10) === +c[10]; };
  const SEP = '[ .,\\-]?';

  // Por contexto: CVV, validade, senha, RG/CNH e CPF (mesmo com dígito errado)
  s = s.replace(/\b(cvv|cvc|c[oó]d(igo)?\.? ?de ?seguran[cç]a)\D{0,6}\d{3,4}\b/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(val(idade)?|venc\w*)\D{0,6}\d{1,2}\s*\/\s*\d{2,4}\b/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(senha|password|pin)\b(\s*(do app|do cart[aã]o|de acesso|do banco))?\s*([eé]|:|=)?\s*\S+/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(rg|cnh|identidade)\b\D{0,12}[\dxX][\d.\-\sxX]{4,15}\d/gi, '$1 [removido por segurança]');
  s = s.replace(new RegExp(`\\b(cpf)\\b\\D{0,15}\\d{3}${SEP}\\d{3}${SEP}\\d{3}${SEP}\\d{1,2}`, 'gi'), 'CPF [removido por segurança]');

  // CPF válido mesmo sem a palavra "cpf"
  s = s.replace(/(?<!\d)\d{3}[ .,]?\d{3}[ .,]?\d{3}[ .,\-]?\d{2}(?!\d)/g, (m) => {
    const d = m.replace(/\D/g, '');
    return d.length === 11 && cpfOk(d) ? '[CPF removido por segurança]' : m;
  });
  // Cartões: 13 a 19 dígitos (com espaço/ponto/traço), começando como cartão (3–6) e com dígito verificador válido
  // (testa também os primeiros 13–19 dígitos, para quando validade/CVV vêm colados no número)
  s = s.replace(/(?<!\d)(?:\d[ .\-\n]?){12,24}\d(?!\d)/g, (m) => {
    const d = m.replace(/\D/g, '');
    if (!/^[3-6]/.test(d) || /^55\d{10,11}$/.test(d)) return m;
    for (const n of [16, 15, 19, 18, 17, 14, 13]) if (d.length >= n && luhn(d.slice(0, n))) return '[número de cartão removido por segurança]';
    return m;
  });
  return s;
};


const entrada = $input.first().json;
const b = entrada.body ?? entrada;
if (!b || !b.data?.key) return [];
if (String(b.event).toLowerCase().replace('_', '.') !== 'messages.upsert') return [];

const d = b.data;
const k = d.key;

// Contas novas do WhatsApp podem chegar como "@lid"; preferimos o número real quando disponível
let jid = k.remoteJid || '';
if (jid.endsWith('@lid')) jid = k.remoteJidAlt || k.senderPn || jid;
if (!jid || jid.endsWith('@g.us') || jid.includes('broadcast') || jid.endsWith('@newsletter')) return [];

const m = d.message || {};
let texto = m.conversation || m.extendedTextMessage?.text || m.imageMessage?.caption ||
  m.videoMessage?.caption || m.documentMessage?.caption || '';

const outrosTipos = {
  audioMessage: '[o cliente enviou um áudio]',
  pttMessage: '[o cliente enviou um áudio]',
  imageMessage: '[o cliente enviou uma imagem]',
  videoMessage: '[o cliente enviou um vídeo]',
  stickerMessage: '[o cliente enviou uma figurinha]',
  documentMessage: '[o cliente enviou um documento]',
  locationMessage: '[o cliente enviou uma localização]',
  contactMessage: '[o cliente enviou um contato]',
};
const midia = ['audioMessage', 'pttMessage'].includes(d.messageType) ? 'audio' : d.messageType === 'imageMessage' ? 'imagem' : '';
if (!texto.trim() || midia === 'audio') texto = texto.trim() || outrosTipos[d.messageType] || '';
if (!texto.trim()) return []; // reações, mensagens apagadas etc.

// Mensagens do cliente: tira comandos internos ([[...]], {{...}}), limita o tamanho e remove dados sensíveis
if (!k.fromMe) texto = texto.replace(/\[\[|\]\]|\{\{|\}\}/g, '').slice(0, 1500);
texto = mascarar(texto);

const numero = jid.split('@')[0].replace(/\D/g, '');
// Vários números da loja: cada número tem conversas separadas. O número principal usa só o telefone
// (compatível com o que já existe); os outros ganham "#nome-da-conexão" na chave da conversa
const principal = config.instancia_principal || 'Sessão Principal';
const slug = String(b.instance || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const telefone = numero + (b.instance && b.instance !== principal && slug ? `#${slug}` : '');
// Compara DDI+DDD+8 últimos dígitos (o WhatsApp às vezes omite o 9 do celular)
const chave = (n) => { const x = String(n).replace(/\D/g, ''); return x.slice(0, 4) + x.slice(-8); };
const numeroTeste = (config.numeros_teste || []).some((n) => chave(n) === chave(numero));

return [{
  json: {
    instancia: b.instance,
    instanciaUrl: encodeURIComponent(b.instance),
    jid,
    telefone,
    numero,
    fromMe: !!k.fromMe,
    msgId: k.id,
    texto: texto.trim(),
    nome: k.fromMe ? '' : String(d.pushName || '').replace(/[\[\]{}$`]/g, '').slice(0, 40),
    midia,
    // Mídia que já vem no webhook (Evolution com base64 ligado); senão o fluxo baixa da Evolution
    midiaBase64: m.base64 || d.base64 || '',
    midiaMimetype: m.audioMessage?.mimetype || m.imageMessage?.mimetype || '',
    legenda: midia === 'imagem' ? mascarar(m.imageMessage?.caption || '') : '',
    // No modo teste qualquer número pode usar #reset (o WhatsApp às vezes esconde o número real atrás de um ID "@lid")
    reset: !k.fromMe && (numeroTeste || !!config.modo_teste) && texto.trim().toLowerCase() === '#reset',
    espera: config.modo_teste ? 1 : 6,
    // Laboratório (só com modo_teste ligado): as respostas vão para o registro de testes, não para o WhatsApp
    lab: !!b.lab && !!config.modo_teste,
  },
}];

const fs = require('fs');
if ($input.first().json.do_bot) return [];

const msg = $('Normalizar').first().json;
const config = JSON.parse(fs.readFileSync('/data/catalogo/config.json', 'utf8'));
const acao = msg.texto.trim().toLowerCase() === '#bot' ? 'retomar' : 'pausar';

return [{ json: { ...msg, acao, pausaMinutos: config.pausa_minutos } }];

// Mensagem digitada pela equipe no WhatsApp da loja: vai para a memória da IA, para o bot saber o que foi combinado
const m = $('Ação da equipe').first().json;
if (m.acao !== 'pausar') return [];
const linha = { type: 'ai', content: `[mensagem da equipe humana]: ${m.texto}`, additional_kwargs: {}, response_metadata: {}, tool_calls: [], invalid_tool_calls: [] };
return [{ json: { telefone: m.telefone, linhas: JSON.stringify([linha]) } }];

const fs = require('fs');
const PASTA = '/data/catalogo/';
const ler = (arquivo) => fs.readFileSync(PASTA + arquivo, 'utf8');

const msg = $('Normalizar').first().json;
// Cada número da loja pode ter atendente, link do app e grupo próprios (catalogo/numeros.json)
let numeros = {};
try { numeros = JSON.parse(ler('numeros.json')); } catch (e) {}
const config = { ...JSON.parse(ler('config.json')), ...(numeros[msg.instancia] || {}) };
const cliente = $('Carregar cliente').first().json;
const texto = String($('Última da fila?').first().json.texto || msg.texto);

const norm = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();

// Números por extenso (comuns em áudio) viram dígitos: "trinta e dois" -> "32"
const EXT = { zero: 0, um: 1, uma: 1, dois: 2, duas: 2, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9, dez: 10, onze: 11, doze: 12, treze: 13, quatorze: 14, catorze: 14, quinze: 15, dezesseis: 16, dezessete: 17, dezoito: 18, dezenove: 19, vinte: 20, trinta: 30, quarenta: 40, cinquenta: 50, sessenta: 60, setenta: 70, oitenta: 80, noventa: 90, cem: 100 };
const extensoParaDigitos = (s) => s
  .replace(/\b(mil novecentos e|dois mil e|dois mil) (\w+)(?: e (\w+))?\b/g, (m, a, b, c) => {
    const base = a.startsWith('mil') ? 1900 : 2000;
    if (EXT[b] === undefined) return m;
    return String(base + EXT[b] + (c && EXT[c] !== undefined ? EXT[c] : 0));
  })
  .replace(/\b(vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa) e (um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove)\b/g, (m, a, b) => String(EXT[a] + EXT[b]))
  .replace(/\b(zero|um|uma|dois|duas|tres|quatro|cinco|seis|sete|oito|nove|dez|onze|doze|treze|quatorze|catorze|quinze|dezesseis|dezessete|dezoito|dezenove|vinte|trinta|quarenta|cinquenta|sessenta|setenta|oitenta|noventa|cem)\b/g, (m) => String(EXT[m]));
// Tira saudações e muletas de fala do início ("opa, sim" -> "sim")
const MULETA = '(oi+|ola|opa|e ai|eai|eae|bom dia|boa tarde|boa noite|entao|tipo|ah+|uai|olha|eh|e|hum+|oxe|oxi|vixe|eita|egua|eras|rapaz|macho|meu rei|visse|vei|mano|mana|maninho|maninha|meu|cara|bah|mas bah|tche|o|ô|dai|pois|xo|po|po vei|so|no|nu|nossa|arreda|olha so|moco|moca|senhor|senhora|pia|guri)';
const semMuleta = (s) => s
  .replace(new RegExp(`^(${MULETA}[,.!\\s]+)+`), '')
  .replace(new RegExp(`[,\\s]+(${MULETA}|visse|viu|ne|uai|so|tche|meu|mano|mana|maninho|moco|senhor|senhora|pia)[.!\\s]*$`), '')
  .trim();
const t0 = norm(texto);
// Idade de outras pessoas não conta ("meu neto de 15 anos")
const t = semMuleta(extensoParaDigitos(t0)
  .replace(/\b(meu|minha|do meu|da minha|pro meu|pra minha|o meu|a minha)\s+(neto|neta|filho|filha|sobrinh[oa]|irma[o]?|afilhad[oa]|primo|prima|enteado|enteada)\b[^.!?]{0,30}?\d{1,3}\s*anos?/g, ' ')
  .replace(/,/g, ' ').replace(/\s+/g, ' ').trim());

// Classificação por IA (gírias e regionalismos) quando as regras fixas não entendem
let cls = null;
try { if ($('Classificar').isExecuted) cls = JSON.parse($('Classificar').first().json.choices[0].message.content); } catch (e) {}

// ---------- dados da loja ----------
const cnpjLoja = String(config.cnpj_loja || '').replace(/[^0-9A-Z]/gi, '').toUpperCase();
const cnpjCadastrado = !!config.cnpj_loja && !/^0{2}\.?0{3}/.test(config.cnpj_loja);
// Sem dado cadastrado, a frase inteira que o usa é removida (para a IA não repetir aviso interno)
const preencher = (s) => {
  let r = s.replaceAll('{{ATENDENTE}}', config.atendente).replaceAll('{{LINK_APP}}', config.link_app).replaceAll('{{LINK_VIDEO}}', config.link_video);
  r = cnpjCadastrado ? r.replaceAll('{{CNPJ_LOJA}}', config.cnpj_loja) : r.replace(/[^\n.!]*\{\{CNPJ_LOJA\}\}[^\n.!]*[.!]?/g, '');
  r = config.endereco_matriz ? r.replaceAll('{{ENDERECO_MATRIZ}}', config.endereco_matriz) : r.replace(/[^\n.!]*\{\{ENDERECO_MATRIZ\}\}[^\n.!]*[.!]?/g, '');
  return r;
};
const dadosEmpresa = [
  cnpjCadastrado ? `- CNPJ: ${config.cnpj_loja}` : '- CNPJ: ainda não cadastrado. Se pedirem, diga que vai confirmar com a equipe e use [[ALERTA: cliente pediu o CNPJ]]. NUNCA invente nem repita números de CNPJ que o cliente sugerir.',
  config.endereco_matriz ? `- Endereço da matriz: ${config.endereco_matriz}` : '- Endereço da matriz: só diga "São Paulo, SP". Se insistirem no endereço completo, diga que vai confirmar e use [[ALERTA: cliente pediu endereço]].',
  config.instagram ? `- Instagram: ${config.instagram}` : '',
  config.site ? `- Site: ${config.site}` : '',
  '- Não temos nenhuma relação com o "Atacadão" do grupo Carrefour; somos outra empresa.',
].filter(Boolean).join('\n');

const agora = new Date();
const saudacaoCliente = (t0.match(/\b(bom dia|boa tarde|boa noite)\b/) || [])[1];
// Fuso pelo DDD (Norte e Centro-Oeste têm horário diferente de Brasília)
const ddd = String(msg.numero || msg.telefone).startsWith('55') ? String(msg.numero || msg.telefone).slice(2, 4) : '';
const fuso = { '68': 'America/Rio_Branco', '69': 'America/Porto_Velho', '92': 'America/Manaus', '97': 'America/Manaus', '95': 'America/Boa_Vista', '65': 'America/Cuiaba', '66': 'America/Cuiaba', '67': 'America/Campo_Grande' }[ddd] || 'America/Sao_Paulo';
const hora = Number(new Intl.DateTimeFormat('pt-BR', { hour: 'numeric', hour12: false, timeZone: fuso }).format(agora));
const saudacaoHora = hora >= 5 && hora < 12 ? 'bom dia' : hora >= 12 && hora < 18 ? 'boa tarde' : 'boa noite';
// Mensagem que é só cumprimento ("oi, tudo bem?", "boa noite!") não é pergunta de verdade
const SO_CUMPRIMENTO = /^((oi+|ola|opa|e ai|eai|eae|salve|hey|bom dia|boa tarde|boa noite|tudo (bem|bom|certo|joia|tranquilo|massa|em paz|nos conformes|beleza|de boa)|td (bem|bom)|de boa|suave|firmeza|como (vai|vc esta|voce esta|esta|ce ta|ta)|beleza|blz|oxe|egua|bah|uai|tche|mano|meu rei)[\s,.!?]*)+$/;
const soCumprimento = SO_CUMPRIMENTO.test(t0) || !!cls?.so_cumprimento;
const perguntouTudoBem = /tudo (bem|bom|certo|joia|tranquilo|massa|em paz|nos conformes|beleza|de boa)|td (bem|bom)|\bblz\b|beleza\?|de boa\?|como (vai|vc esta|voce esta|esta|ce ta)/.test(t0);

const estado = {
  etapa: cliente.bloqueado ? 'bloqueado' : cliente.etapa,
  perfil: cliente.perfil || '',
  segmento: cliente.segmento || '',
  cnpj: cliente.cnpj || '',
  empresa: cliente.empresa || '',
  tentativas: Number(cliente.tentativas) || 0,
  link_enviado: !!cliente.link_enviado,
  turnos_sem_link: Number(cliente.turnos_sem_link) || 0,
  turnos_desde_link: cliente.turnos_desde_link == null ? 99 : Number(cliente.turnos_desde_link),
  notas: cliente.notas || '',
  pendente: cliente.pendente || '',
  pediu_apagar: false,
  ultimo_alerta: cliente.ultimo_alerta || '',
  sem_android: !!cliente.sem_android || /iphone|\bios\b|\bapple\b|nao tenho android|ninguem (aqui )?tem android|meu (celular|cel) e iphone/.test(t0),
};

// Primeiro nome do WhatsApp, só se parecer nome de pessoa
const NAO_NOME = /^(seu|sr|sra|dona|dr|dra|adega|bar|distribuidora|mercado|mercadinho|loja|deposito|conveniencia|atacadao|emporio|lanchonete|restaurante|pizzaria|padaria|tabacaria|boteco|casa|comercial|grupo|empresa|vendas|delivery)$/;
const primeiro = (cliente.nome || '').trim().split(/\s+/)[0] || '';
const primeiroNome = /^[A-Za-zÀ-ÿ]{2,15}$/.test(primeiro) && !NAO_NOME.test(norm(primeiro))
  ? primeiro[0].toUpperCase() + primeiro.slice(1).toLowerCase() : '';

const base = {
  telefone: msg.telefone, numero: msg.numero || msg.telefone, instancia: msg.instancia, jid: msg.jid, instanciaUrl: msg.instanciaUrl, lab: !!msg.lab,
  nome: primeiroNome || '', texto, config, textoLink: preencher(ler('texto-link-app.txt')),
  textoOportunidade: ler('texto-oportunidade-lojista.txt'),
  // Cliente desconfiado/reclamando: o link não é empurrado nesta resposta (a não ser que ele peça)
  segurarLink: (/golpe|fraude|confi|duvido|engan|piramide|furada|suspeit|desconfi|e serio|verdade mesmo|reclam|procon|nao chegou|nunca chegou|absurdo|\b171\b|cilada|armac|truque|cabreir|pe atras|tem coisa|esquisit|estranh|\bcao\b|treta|sacanagem|barato demais|pitiu/.test(t0) || !!cls?.desconfiado)
    && !/\b(link|app|aplicativo|baixar|cadastr)\b/.test(t0),
};
// Minutos desde o último aviso à equipe (para não mandar a mesma dúvida no grupo a cada mensagem)
base.minutosDesdeAlerta = cliente.ultimo_alerta_em ? (agora - new Date(cliente.ultimo_alerta_em)) / 60000 : null;
// iPhone, mas vai usar o Android de outra pessoa ("baixo no celular do primo")
base.androidDeOutro = /(primo|prima|filh\w*|net[oa]s?|espos[oa]|marido|mulher|irm\w*|mae|pai|amig\w*|funcionari\w*|sobrinh\w*|cunhad\w*|vizinh\w*|socio|alguem)( aqui)? (que )?(tem|usa) android|android d[oa] |(celular|cel) d[oa] (meu |minha )?(primo|prima|filh|net|espos|marido|mulher|irm|mae|pai|amig|funcionari|sobrinh|cunhad|vizinh|socio)/.test(t0);
// Pedido de link de verdade ("manda o link", "cadê o app"), não só citar o app ("vou baixar o app")
base.pediuLink = /(manda|mande|envia|envie|passa|passe|reenvia|me (da|de|ve)|cade|qual (e|eh)|perdi|nao (achei|encontrei|abriu|abre|consegui)|de novo|outra vez|quero|pode).{0,25}\b(link|app|aplicativo)\b|\b(link|app|aplicativo)\b.{0,15}(de novo|nao (abre|abriu|funciona)|por favor|pf|pfv)|^(o )?link\??$/.test(t0);
const txt = (text) => ({ tipo: 'texto', text });
const AVISO_SENSIVEL = /removido por seguranca/.test(t0)
  ? [txt('Por segurança, não precisa mandar *dados de cartão, CPF, senha ou documentos* por aqui 🔒 Tudo isso é feito só no app, e eu já descartei essa informação.')]
  : [];
const responder = (acao, mensagens = [], extra = {}) => {
  if (AVISO_SENSIVEL.length && acao === 'enviar') mensagens = [...AVISO_SENSIVEL, ...mensagens];
  if (AVISO_SENSIVEL.length && acao === 'ia') extra = { ...extra, prefixo: [...AVISO_SENSIVEL, ...(extra.prefixo || [])] };
  return [{ json: { ...base, acao, mensagens, estado, humano: false, alerta: false, ...extra } }];
};
const irPara = (etapa) => { estado.etapa = etapa; estado.tentativas = 0; };
const guardarPergunta = () => {
  const junto = [estado.pendente, texto].filter(Boolean).join(' / ');
  estado.pendente = junto.length > 400 ? junto.slice(-400).replace(/^\S*\s/, '') : junto;
};

// ---------- classificadores ----------
function lerIdade(s) {
  // "faz 15 anos", "há 10 anos", "15 anos de bar": tempo, não idade
  s = s.replace(/\b(faz|ha|desde|tem|ja tem|a) \d{1,3} anos?\b/g, ' ').replace(/\s+/g, ' ').trim();
  if (/\b(nao|nunca) (sou|fui|e|eh) (mais )?(de )?menor\b/.test(s)) return 'S';
  if (/\bnao (tenho|fiz|completei|sou)( ainda)? (18|dezoito|maior|de maior)\b|\b(quase|vou fazer|vou completar|faco|completo) (os )?18\b/.test(s)) return 'N';
  // Número explícito de idade decide primeiro ("tenho 30 anos, ainda não comprei" = adulto)
  const NAO_IDADE = '(?!( anos?)? ?(de|do|da|no|na|em)? ?(bar|boteco|casa|mercado|loja|comercio|empresa|experiencia|ramo|estrada|servico|filh|caix|fard|garraf|lat|un|real|reais|pergunt|lojas|bares))';
  const num = s.match(new RegExp(`^(?:sim,? ?|s,? ?|ss,? ?)?(?:tenho|tenhu|tnh|to com|tou com|estou com|com|idade:?)? ?(?:sim |ja )?(\\d{1,3}) ?(?:anos?|a|aninhos)?(?: ainda| ja| sim| completos| viu| ne)?\\s*[!.]*$`))
    || s.match(new RegExp(`\\b(?:tenho|tenhu|tnh|to com|tou com|estou com|idade:?) (\\d{1,3})(?: anos?| a)?\\b${NAO_IDADE}`))
    || s.match(new RegExp(`\\b(\\d{1,3}) anos\\b${NAO_IDADE}`));
  if (num) { const n = +num[1]; if (n >= 18 && n <= 110) return 'S'; if (n >= 8 && n < 18) return 'N'; }
  if (/\bnao (tenho|fiz|completei|sou)( ainda)? (18|dezoito|maior|de maior)\b|\b(quase|vou fazer|vou completar|faco|faz|completo|fazendo)\b.{0,15}\b18\b|\b18\b.{0,25}\bque vem\b|^ainda nao\b|^quase\b|\b(sou )?(de )?menor\b|\bnao tenho idade\b/.test(s)) return 'N';
  const nasc = s.match(/^(19[2-9]\d|20[0-2]\d)$|nasci (em |no ano de )?(?:\d{1,2}\/\d{1,2}\/)?(19[2-9]\d|20[0-2]\d)/);
  if (nasc) { const a = agora.getFullYear() - (+(nasc[1] || nasc[3])); return a >= 19 ? 'S' : a <= 17 ? 'N' : 'E'; }
  if (/(\+ ?18|18 ?\+|mais de (1[89]|[2-9]\d)|acima de 18|maior de 18|maior de idade|\bde maior\b|\bsou maior\b|18 anos ou mais|passei dos \d{2}|aposentad|tenho net[oa]s?\b|sou (veio|velho|coroa)|maior e vacinado|idade pra ser)/.test(s)) return 'S';
