// CNPJ numérico ou alfanumérico (novo formato da Receita a partir de 2026)
function cnpjValido(c) {
  if (!/^[0-9A-Z]{12}\d{2}$/.test(c) || /^(.)\1+$/.test(c)) return false;
  const dv = (b) => {
    let soma = 0, peso = b.length - 7;
    for (const ch of b) { soma += (ch.charCodeAt(0) - 48) * peso--; if (peso < 2) peso = 9; }
    const r = soma % 11;
    return r < 2 ? 0 : 11 - r;
  };
  return dv(c.slice(0, 12)) === +c[12] && dv(c.slice(0, 13)) === +c[13];
}
function lerCnpj(original, s) {
  // Normaliza o jeito falado/transcrito: "11.222.333, barra 0001, traço 81"
  const limpo = original.replace(/,\s*/g, ' ').replace(/\s*\bbarra\b\s*/gi, '/').replace(/\s*\b(tra[cç]o|h[ií]fen)\b\s*/gi, '-').replace(/\s*\bponto\b\s*/gi, '.');
  const numericos = (limpo.match(/\d[\d.\/\-\s]*\d/g) || []).map((b) => b.replace(/\D/g, ''));
  const alfanumericos = (limpo.toUpperCase().match(/\b[0-9A-Z]{2}\.?[0-9A-Z]{3}\.?[0-9A-Z]{3}\/?[0-9A-Z]{4}-?\d{2}\b/g) || []).map((b) => b.replace(/[^0-9A-Z]/g, ''));
  const valido = [...numericos, ...alfanumericos].find(cnpjValido);
  if (valido) return { r: 'ACEITA', cnpj: valido };
  const digitos = numericos.sort((a, b) => b.length - a.length)[0] || '';
  if (digitos.length === 11 || /cpf removido/.test(s)) return { r: 'CPF' };
  if (digitos.length >= 12) return { r: 'INVALIDO' };
  if (/perai|pera ai|espera|vou (ver|pegar|procurar|olhar|buscar)|ja (te )?(mando|passo)|te (mando|passo|envio) (ja|agora)|um minuto|um momento|so um (minuto|momento)/.test(s)) return { r: 'AGUARDA' };
  if (/\bmei\b/.test(s) && !/nao (tenho|sou)/.test(s)) return { r: 'MEI' };
  if (/^(n+|nao+|naum|nop|nope|sem|to sem|nenhum)[ !.]*$|pul(a|ar)\b|\bn(ao)? (tenho|sei|lembro)|sem cnpj|to sem|tou sem|estou sem|nao quero|nao vou|nao passo|nao precisa|depois|agora nao|mais tarde|outra hora|nao (estou|to|tou) com|deixa (pra|para) la|prefiro nao|esqueci|informal|formaliz|nao abri|\bcpf\b|segue sem|seguir sem|pode seguir|sem problema/.test(s)) return { r: 'PULA' };
  if (/(pra|para|por) ?que.{0,20}cnpj|porque.{0,20}cnpj|precisa (do|de) cnpj|cnpj (e )?obrigatori/.test(s)) return { r: 'EXPLICA' };
  return { r: 'OUTRO' };
}

