// Remove dados sensíveis (cartão, CVV, validade, CPF, senha, RG/CNH) antes de guardar qualquer coisa
const mascarar = (entrada) => {
  let s = String(entrada);
  const luhn = (n) => { let soma = 0, dobra = false; for (let i = n.length - 1; i >= 0; i--) { let x = +n[i]; if (dobra) { x *= 2; if (x > 9) x -= 9; } soma += x; dobra = !dobra; } return soma % 10 === 0; };
  const cpfOk = (c) => { if (/^(\d)\1+$/.test(c)) return false; const dv = (n) => { let t = 0; for (let i = 0; i < n; i++) t += +c[i] * (n + 1 - i); const r = (t * 10) % 11; return r === 10 ? 0 : r; }; return dv(9) === +c[9] && dv(10) === +c[10]; };
  const SEP = '[ .,\\-]?';

  // Por contexto: CVV, validade, senha, RG/CNH e CPF (mesmo com dígito errado)
  s = s.replace(/\b(cvv|cvc|c[oó]d(igo)?\.? ?de ?seguran[cç]a)\D{0,6}\d{3,4}\b/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(val(idade)?|venc\w*)\D{0,6}\d{1,2}\s*\/\s*\d{2,4}\b/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(senha|password|pin)\b(\s*(do app|do cart[aã]o|de acesso|do banco))?\s*([eé]|:|=)?\s*\S+/gi, '$1 [removido por segurança]');
  s = s.replace(/\b(rg|cnh|identidade)\b\D{0,12}[\dxX][\d.\-\sxX]{4,15}\d/gi, '$1 [removido por segurança]');
  s = s.replace(new RegExp(`\\b(cpf)\\b\\D{0,15}\\d{3}${SEP}\\d{3}${SEP}\\d{3}${SEP}\\d{1,2}`, 'gi'), 'CPF [removido por segurança]');

  // CPF válido mesmo sem a palavra "cpf"
  s = s.replace(/(?<!\d)\d{3}[ .,]?\d{3}[ .,]?\d{3}[ .,\-]?\d{2}(?!\d)/g, (m) => {
    const d = m.replace(/\D/g, '');
    return d.length === 11 && cpfOk(d) ? '[CPF removido por segurança]' : m;
  });
  // Cartões: 13 a 19 dígitos (com espaço/ponto/traço), começando como cartão (3–6) e com dígito verificador válido
  // (testa também os primeiros 13–19 dígitos, para quando validade/CVV vêm colados no número)
  s = s.replace(/(?<!\d)(?:\d[ .\-\n]?){12,24}\d(?!\d)/g, (m) => {
    const d = m.replace(/\D/g, '');
    if (!/^[3-6]/.test(d) || /^55\d{10,11}$/.test(d)) return m;
    for (const n of [16, 15, 19, 18, 17, 14, 13]) if (d.length >= n && luhn(d.slice(0, n))) return '[número de cartão removido por segurança]';
    return m;
  });
  return s;
};

