  return s;
};

const msg = $('Normalizar').first().json;
const descricao = String($input.first().json.choices?.[0]?.message?.content || '').replace(/\[\[|\]\]|\{\{|\}\}/g, '').trim();
const partes = [descricao ? `[o cliente enviou uma imagem: ${descricao}]` : '[o cliente enviou uma imagem]'];
if (msg.legenda) partes.push(msg.legenda);
return [{ json: { ...msg, texto: mascarar(partes.join('\n')).slice(0, 1500) } }];

// Monta a consulta para a IA classificar a mensagem do cliente (gírias, regionalismos, áudio transcrito)
const c = $('Carregar cliente').first().json;
const texto = String($('Última da fila?').first().json.texto || '');
const perguntas = {
  novo: '(primeira mensagem do cliente; ainda não perguntamos nada)',
  idade: 'Você tem 18 anos ou mais?',
  confirma_menor: 'Qual a sua idade?',
  perfil: 'Você está comprando para consumo próprio ou para o seu negócio (bar, restaurante, mercado, adega, revenda)?',
  cnpj: 'Se tiver aí, me manda o CNPJ da sua empresa (é opcional).',
};
const instrucao = `Você classifica mensagens de clientes de uma distribuidora de bebidas no WhatsApp brasileiro. Entenda gírias, abreviações, erros de digitação, áudio transcrito e regionalismos de TODO o Brasil (ex.: "nó"/"uai"/"sô" mineiros, "bah"/"tchê"/"capaz" gaúchos, "oxe"/"visse"/"meu rei" nordestinos, "égua"/"maninho" do Norte, "véi" de Brasília). Interjeições como "nó", "bah", "oxe", "égua" NÃO significam "não".
Responda SOMENTE um JSON com:
{"idade": "maior" | "menor" | "nao_respondeu",
 "idade_anos": número ou null,
 "perfil": "consumo" | "negocio" | "nao_disse",
 "tipo_negocio": "bar" | "outro" | null,
 "tem_pergunta": true | false,
 "pos_venda": true | false,
 "desconfiado": true | false,
 "so_cumprimento": true | false,
 "problema_app": true | false}
Regras:
- idade/idade_anos: só a idade do PRÓPRIO cliente (ignore filhos, netos, "15 anos de bar", tempo de empresa). "maior" se ele indicar que tem 18+ (sim, claro, tenho, de maior, idade >= 18, aposentado...). "menor" só se ELE disser que tem menos de 18. Na dúvida: "nao_respondeu". Se ele se recusa a responder ou desconversa ("nem vem com essa", "não interessa", "passa logo o preço", "cê acha que tá falando com quem?"), é "nao_respondeu": precisa de um sim ou da idade.
- perfil: "negocio" se compra para revender ou para um estabelecimento (bar, boteco, adega, mercado, flutuante, barraca, conveniência, restaurante, distribuidora, ambulante, vende bebida...). "consumo" se é para casa, festa, evento, churrasco, festa da firma. tipo_negocio "bar" para bar/boteco/adega/quiosque/barraca/conveniência/flutuante/tabacaria e parecidos.
- tem_pergunta: true se, além de responder, o cliente perguntou ou pediu algo que precisa de resposta (preço, entrega, prazo, pagamento, golpe?, etc.). Cumprimentos ("tudo bem?") NÃO contam.
- pos_venda: true SÓ se ele fala de um pedido que JÁ FEZ (não chegou, veio errado, cobrança, cancelar, comprovante). Quem quer FAZER um pedido ou pergunta como será a entrega é false.
- desconfiado: true se demonstra desconfiança (golpe, 171, cilada, "tem coisa aí", "esquisito", "barato demais").
- so_cumprimento: true se a mensagem é só cumprimento/saudação.
- problema_app: true se o cliente diz que JÁ está tentando (ou tentou) baixar/instalar/usar o app e não conseguiu, ou descreve o que apareceu na tela (erro, página, botão). Só perguntar "tem app?" é false.`;
const pergunta = perguntas[c.etapa] || '';
// Modelos que "pensam" (gpt-5/gpt-6...) usam outros parâmetros que os antigos (gpt-4...)
const MODELO = '__MODELO_CHAT__';
const pensa = !/^gpt-4/.test(MODELO);
return [{ json: { body: {
  model: MODELO,
  ...(pensa ? { reasoning_effort: 'low', max_completion_tokens: 2000 } : { temperature: 0, max_tokens: 120 }),
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: instrucao },
    { role: 'user', content: `Pergunta que o atendente fez por último: "${pergunta}"\nMensagem do cliente: <<${texto.slice(0, 800)}>>` },
  ],
} } }];

// Junta o nome da empresa (consulta do CNPJ) ao que a IA sabe, para ela citar na resposta
const r = $('Roteador').first().json;
const j = $input.first().json || {};
// MEI costuma ter como razão social o nome da pessoa + CPF: aí não mostra (pode nem ser quem está conversando)
const fantasia = j.nome_fantasia || j.estabelecimento?.nome_fantasia || j.fantasia || '';
const razao = j.razao_social || j.nome || '';
const pareceMei = /\d|\*/.test(razao) || /^MEI$|MICROEMPREENDEDOR/i.test(String(j.natureza_juridica || j.descricao_porte || ''));
const nome = (fantasia || (pareceMei ? '' : razao)).trim();
const estado = { ...r.estado, empresa: nome };
const aviso = nome
  ? `\n\n# CNPJ CONSULTADO AGORA\nO CNPJ que o cliente mandou é da empresa *${nome}*. Mencione o nome numa frase curta (ex.: "Achei aqui: *${nome}* ✅") antes de anunciar o catálogo.`
  : '\n\n# CNPJ RECEBIDO AGORA\nO cliente mandou um CNPJ válido, mas a consulta não trouxe o nome da empresa. Agradeça e diga que já anotou.';
return [{ json: { ...r, estado, ia: { ...r.ia, systemPrompt: r.ia.systemPrompt + aviso } } }];

// A IA falhou (OpenAI fora do ar, erro etc.): o cliente nunca fica sem resposta
const r = $('Resposta CNPJ').isExecuted ? $('Resposta CNPJ').first().json : $('Roteador').first().json;
const mensagens = [...(r.prefixo || []), ...(r.reserva || [{ tipo: 'texto', text: 'Opa, tive uma instabilidade aqui 🙏 Já já te respondo, tá?' }])];
return [{ json: { ...r, acao: 'enviar', mensagens, estado: r.estado, catalogoEnviado: !!r.catalogo, humano: false, alerta: !!r.falhaAvisa,
  motivo: '⚠️ A IA falhou ao responder este cliente. Vale responder manualmente.' } }];

// Quando o cliente mandou CNPJ, os dados vêm da consulta (com o nome da empresa); senão, do Roteador
const r = $('Resposta CNPJ').isExecuted ? $('Resposta CNPJ').first().json : $('Roteador').first().json;
let s = String($input.first().json.output || '').trim();
const conducao = r.ia?.modo === 'conducao';
// Catálogo sob demanda: quem foi direto para a ajuda com o app recebe quando pedir
const catalogo = r.catalogo || (!conducao && r.catalogoPendente && /\[\[\s*CATALOGO\s*\]\]/i.test(s) ? r.catalogoPendente : null);

const humano = /\[\[\s*HUMANO\s*:?\s*([^\]]*)\]\]/i.exec(s);
const alerta = /\[\[\s*ALERTA\s*:?\s*([^\]]*)\]\]/i.exec(s);
// Link enviado nas últimas 2 respostas só sai de novo se o cliente pedir
const linkMuitoRecente = r.estado.link_enviado && (r.estado.turnos_desde_link ?? 99) < 3 && !r.pediuLink;
const enviarLink = !conducao && !r.segurarLink && (!r.estado.sem_android || r.androidDeOutro || r.pediuLink) && !linkMuitoRecente && /\[\[\s*LINK_APP\s*\]\]/i.test(s);
const pediuVideo = !conducao && /\[\[\s*VIDEO\s*\]\]/i.test(s);
const oportunidade = !conducao && !catalogo?.some((m) => m.text === r.textoOportunidade) && /\[\[\s*OPORTUNIDADE\s*\]\]/i.test(s);
// Silêncio só para "ok"/"valeu" curto: se o cliente pergunta, pede algo ou diz que está esperando, ele recebe resposta
const textoCliente = String(r.texto || '');
const merecemResposta = /\?|esperando|aguardando|cad[eê]|responde|me (fala|diz|explica)/i.test(textoCliente);
const silencio = /\[\[\s*SILENCIO\s*\]\]/i.test(s) && !merecemResposta && !catalogo;
// Anotações sobre o cliente: descarta qualquer coisa que pareça promessa/condição comercial ou dado sensível
const notas = [...s.matchAll(/\[\[\s*NOTA\s*:?\s*([^\]]*)\]\]/gi)]
  .map((m) => m[1].trim().slice(0, 120))
  .filter((n) => n && !/desconto|vip|gerente|aprovad|%|gr[aá]tis|prometid|liberad|cortesia|cpf|cart[aã]o|senha|\d{6,}/i.test(n));

// O catálogo entra onde a IA marcou [[CATALOGO]] (ou no fim, se ela esqueceu)
const MARCA = '@@CATALOGO@@';
s = s.replace(/\[\[\s*CATALOGO\s*\]\]/i, catalogo ? MARCA : '');

// Só os links da loja podem sair nas respostas
const permitidos = [r.config.link_app, r.config.link_video, r.config.instagram, r.config.site].filter(Boolean);
s = s.replace(/\[\[[^\]]*\]\]/g, '')
  .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2')
  .replace(/https?:\/\/[^\s)]+/g, (url) => (permitidos.some((p) => url.startsWith(p)) ? url : ''))
  .replace(/\*\*(.+?)\*\*/g, '*$1*')
  .replace(/__(.+?)__/g, '_$1_')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Antes do catálogo o link não vai: tira ofertas/promessas de link que a IA tenha escrito
if (conducao) {
  const promessaLink = (f) => /(link|app|aplicativo)/i.test(f) && /\?\s*$|vou (te )?(mandar|enviar|passar)|j[aá] (te )?(mando|envio|vou)/i.test(f);
  s = s.split('\n').map((l) => l.split(/(?<=[.!?])\s+/).filter((f) => !promessaLink(f)).join(' ')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}
// Link indo agora (ou enviado há pouco): tira a frase "quer que eu te mande o link?" do texto da IA
if (enviarLink || linkMuitoRecente) {
  const ofereceLink = (f) => /(link|app|aplicativo)/i.test(f) && /(quer|posso|deseja|gostaria|prefere|bora).{0,40}(mand|envi|pass)|\?\s*$/i.test(f) && !/(conseguiu|deu certo|funcionou)/i.test(f);
  s = s.split('\n').map((l) => l.split(/(?<=[.!?])\s+/).filter((f) => !ofereceLink(f)).join(' ')).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

// Pedaço só com "---" ou vazio não vira balão
// Parágrafos viram balões (como uma pessoa digitando), no máximo 3 por trecho
const emBaloes = (x) => {
  if (/\n\s*---\s*\n/.test(x) || /^\s*([-•▪️*]|\d+[.)])\s/m.test(x)) return x;
  const p = x.split(/\n\s*\n/).map((y) => y.trim()).filter(Boolean);
  if (p.length < 2) return x;
  const n = Math.min(3, p.length), tam = Math.ceil(p.length / n);
  return Array.from({ length: n }, (_, i) => p.slice(i * tam, (i + 1) * tam).join('\n\n')).filter(Boolean).join('\n---\n');
};
const limpa = (x) => (x.replace(/^\s*---\s*$/gm, '').trim() ? x.replace(/^(\s*---\s*\n)+|(\n\s*---\s*)+$/g, '').trim() : '');
let [antes, depois = ''] = s.split(MARCA);
antes = limpa(antes); depois = limpa(depois);
if (!catalogo) { antes = limpa([antes, depois].filter(Boolean).join('\n')); depois = ''; }
antes = emBaloes(antes); depois = emBaloes(depois);

const mensagens = [...(r.prefixo || [])];
if (antes && !silencio) mensagens.push({ tipo: 'texto', text: antes });
if (catalogo) mensagens.push(...catalogo);
if (depois && !silencio) mensagens.push({ tipo: 'texto', text: depois });
if (oportunidade) mensagens.push({ tipo: 'texto', text: r.textoOportunidade });
// Link enviado há pouco: só relembra em um balão curto, sem repetir o bloco inteiro
const linkRecente = r.estado.link_enviado && (r.estado.turnos_desde_link ?? 99) < 5;
if (enviarLink) mensagens.push({ tipo: 'texto', text: linkRecente ? `📲 App: ${r.config.link_app}` : r.textoLink });
// Vídeo de instalação: vai junto com o PRIMEIRO link e, depois, quando a IA pede ([[VIDEO]]) para quem teve dificuldade
const video = r.config.video_instalacao ? { tipo: 'video', arquivo: r.config.video_instalacao, legenda: r.config.legenda_video || '' } : null;
const primeiroLink = enviarLink && !r.estado.link_enviado;
if (video && (primeiroLink || pediuVideo)) mensagens.push(video);
// Resposta vazia sem motivo (ex.: só um comando que foi descartado): manda algo em vez de deixar o cliente no vácuo
if (!mensagens.length && !silencio && !humano) {
  mensagens.push(...(conducao && r.reserva?.length ? r.reserva
    : [{ tipo: 'texto', text: merecemResposta ? 'Tô por aqui sim 😊 Se precisar de qualquer coisa, é só me chamar!' : 'Me conta um pouquinho mais pra eu te ajudar melhor? 😊' }]));
}

// Mesma dúvida já enviada à equipe há pouco: não manda de novo no grupo
const palavras = (x) => new Set(String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]{4,}/g) || []);
const parecido = (a, b) => { const A = palavras(a), B = palavras(b); if (!A.size || !B.size) return false; let n = 0; for (const w of A) if (B.has(w)) n++; return n / Math.min(A.size, B.size) >= 0.5; };
const motivoAlerta = (alerta?.[1] || '').trim() || 'dúvida do cliente';
const alertaRepetido = !!alerta && r.minutosDesdeAlerta != null && (r.minutosDesdeAlerta < 15 || (r.minutosDesdeAlerta < 720 && parecido(motivoAlerta, r.estado.ultimo_alerta)));
const avisarAlerta = !humano && !!alerta && !alertaRepetido;

const estado = { ...r.estado };
// A pergunta guardada só é esquecida quando a conversa já está livre (a IA já teve o catálogo para responder)
if (!conducao) estado.pendente = '';
estado.alertou_agora = avisarAlerta || !!humano;
if (estado.alertou_agora) estado.ultimo_alerta = ((humano || alerta)?.[1] || '').trim().slice(0, 120) || motivoAlerta;
estado.link_enviado = r.estado.link_enviado || enviarLink;
if (enviarLink) { estado.turnos_sem_link = 0; estado.turnos_desde_link = 0; }
if (catalogo) estado.notas = String(estado.notas || '').split(' | ').filter((n) => !n.startsWith('catálogo ainda não enviado')).join(' | ');
if (notas.length) estado.notas = [r.estado.notas, ...notas].filter(Boolean).join(' | ').slice(-800);

return [{
  json: {
    ...r, acao: 'enviar', mensagens, estado, catalogoEnviado: !!catalogo, catalogo, videoEnviado: mensagens.some((m) => m.tipo === 'video'),
    humano: !!humano,
    alerta: avisarAlerta,
    motivo: ((humano || alerta)?.[1] || '').trim() || 'Cliente solicitou atendimento',
  },
}];

const d = $('Dados do envio').first().json;
const grupos = $input.all().map((i) => i.json);
const alvo = (d.config.grupo_equipe || '').trim().toLowerCase();
const grupo = grupos.find((g) => (g.subject || '').trim().toLowerCase() === alvo);
// Sem grupo, não pausa o bot (o cliente não fica no vácuo)
if (!grupo) return [];

const perfil = d.estado.perfil === 'negocio'
  ? `Negócio${d.estado.empresa ? ` — ${d.estado.empresa}` : ''}${d.estado.cnpj ? ` (CNPJ ${d.estado.cnpj})` : ''}`
  : d.estado.perfil === 'consumo' ? 'Consumo próprio' : 'Ainda não informado';

// Urgente = cliente esperando com o bot pausado; Quando der = o bot segue atendendo
const titulo = d.realerta ? '🔴 *URGENTE — CLIENTE AINDA AGUARDANDO*'
  : d.humano ? '🔴 *URGENTE — cliente esperando atendimento* (bot pausado)'
  : '🟡 *QUANDO DER — dúvida para a equipe* (bot continua atendendo)';
const linhas = [
  titulo,
  '',
  `👤 *Cliente:* ${d.nome || 'sem nome'}`,
  `📱 *WhatsApp:* wa.me/${d.numero || d.telefone}`,
  `📞 *Chegou pelo número:* ${d.config.atendente} (${d.instancia || 'principal'})`,
  `🏷️ *Perfil:* ${perfil}`,
  `📝 *Motivo:* ${d.motivo}`,
  `💬 *Mensagem:* "${String(d.texto).slice(0, 120)}${d.texto.length > 120 ? '…' : ''}"`,
  d.estado.notas ? `📒 *O que já sabemos:* ${d.estado.notas}` : '',
  '',
  d.humano
    ? `⏸️ O bot foi *pausado* nesta conversa. Responda o cliente pelo WhatsApp da loja.\n▶️ Para devolver ao bot, envie *#bot* na conversa do cliente (ou aguarde ${d.config.pausa_minutos} min sem mensagens).`
    : '▶️ O bot continua respondendo. Se quiser assumir, é só responder o cliente pelo WhatsApp da loja.',
].filter((l, i, arr) => l !== '' || arr[i - 1] !== '');

return [{ json: { instanciaUrl: d.instanciaUrl, body: { number: grupo.id, text: linhas.join('\n') } } }];

const fs = require('fs');
const d = $('Dados do envio').first().json;
const url = (rota) => `http://evolution:8080/message/${rota}/${d.instanciaUrl}`;

// "delay" faz o WhatsApp mostrar "digitando..." antes de cada mensagem
// "---" sozinho numa linha divide o texto em balões separados, como uma pessoa digitando
// Mídia que não existe na pasta (ex.: vídeo apagado ou renomeado): vira texto, para o envio não quebrar
const existe = (arquivo) => { try { return fs.statSync('/data/catalogo/' + arquivo).isFile(); } catch (e) { return false; } };
const baloes = (d.mensagens || []).flatMap((m) => {
  if (m.tipo === 'texto') return m.text.split(/(?:^|\n)\s*---\s*(?:\n|$)/).map((t) => t.trim()).filter(Boolean).map((text) => ({ tipo: 'texto', text }));
  if (m.tipo === 'video' && !existe(m.arquivo)) return d.config?.link_video ? [{ tipo: 'texto', text: `🎥 Vídeo de como instalar: ${d.config.link_video}` }] : [];
  if (m.tipo === 'imagem' && !existe(m.arquivo)) return [];
  return [m];
});

// Laboratório: nada vai para o WhatsApp; cada balão é gravado no registro de testes
if (d.lab) {
  const avisos = d.humano ? [`[SISTEMA: equipe chamada e bot pausado — ${d.motivo}]`] : d.alerta ? [`[SISTEMA: dúvida enviada à equipe, bot continua — ${d.motivo}]`] : [];
  return [...baloes.map((m) => (m.tipo === 'imagem' ? '[IMAGEM: arte do catálogo]' : m.tipo === 'video' ? `[VÍDEO: como instalar o app] ${m.legenda || ''}`.trim() : m.text)), ...avisos]
    .map((text) => ({ json: { telefone: d.telefone, url: 'http://n8n:5678/webhook/lab-saida', body: { telefone: d.telefone, text } } }));
}

return baloes.map((m) => {
  if (m.tipo === 'imagem') {
    const media = fs.readFileSync('/data/catalogo/' + m.arquivo).toString('base64');
    return { json: { telefone: d.telefone, url: url('sendMedia'), body: {
      number: d.jid, mediatype: 'image', mimetype: 'image/jpeg', media, fileName: m.arquivo, caption: '', delay: d.config?.modo_teste ? 300 : 1500,
    } } };
  }
  if (m.tipo === 'video') {
    const media = fs.readFileSync('/data/catalogo/' + m.arquivo).toString('base64');
    return { json: { telefone: d.telefone, url: url('sendMedia'), body: {
      number: d.jid, mediatype: 'video', mimetype: 'video/mp4', media, fileName: m.arquivo, caption: m.legenda || '', delay: d.config?.modo_teste ? 300 : 1500,
    } } };
  }
  const delay = d.config?.modo_teste ? 300 : Math.min(5000, 1200 + m.text.length * 25);
  return { json: { telefone: d.telefone, url: url('sendText'), body: { number: d.jid, text: m.text, delay } } };
});

// Grava na memória da IA o que saiu sem passar por ela (mensagens fixas e o catálogo), para ela ter o contexto completo
const d = $('Dados do envio').first().json;
const resumo = (m) => m.tipo === 'imagem' ? '[enviei a imagem do catálogo]' : m.tipo === 'video' ? '[enviei o vídeo de como instalar o app]'
  : m.text.startsWith('📋') ? '[enviei o catálogo completo em texto, com todos os produtos e preços]'
  : m.text.replace(/\n\s*---\s*\n/g, '\n');
const humano = (content) => ({ type: 'human', content, additional_kwargs: {}, response_metadata: {} });
const bot = (content) => ({ type: 'ai', content, additional_kwargs: {}, response_metadata: {}, tool_calls: [], invalid_tool_calls: [] });

const linhas = [];
if (!d.ia && d.acao !== 'apagar') {
  linhas.push(humano(d.texto));
  if (d.mensagens?.length) linhas.push(bot(d.mensagens.map(resumo).join('\n')));
} else {
  if (d.catalogoEnviado) linhas.push(bot(`[o sistema enviou o catálogo: imagem + lista completa de preços${d.catalogo.length > 2 ? ' + mensagem dos kits em comodato' : ''}]`));
  if (d.videoEnviado) linhas.push(bot('[o sistema enviou o vídeo (arquivo) com o passo a passo de como instalar o app]'));
}
if (!linhas.length) return [];
return [{ json: { telefone: d.telefone, linhas: JSON.stringify(linhas) } }];
